Ext._define('apd.resource.ResourceGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'apd.resource.ResourceWindow',

    configOrderToolBar: ['openDecision','openText','search', '-', '->'],

    getOpenDecisionAction: function(){
        if(!this.openManager)
            this.openManager = Ext._create('Ext.Button', {
                text: 'Decisão',
                scope: this,
                iconCls: 'icon-apd icon-apd-decision-resource',
                handler: this.decision
            });
    
        return this.openManager;
    },

    getOpenTextAction: function(){
        if(!this.openText)
            this.openText = Ext._create('Ext.Button', {
                text: 'Ver texto do recurso',
                scope: this,
                iconCls: 'icon-apd icon-apd-blue-document-copy',
                handler: this.textwindow
            });
    
        return this.openText;
    },

    textwindow: function(){
        var selected = this.getSelectionModel().getSelected();
        if (selected){
            Ext._create('Ext.Window', {
                title: 'Informações do Pedido de Recurso',
                modal: true,
                frame: true,
                width: 800,
                height: 500,
                items: [
                    {
                        xtype: 'fieldset',
                        title: '',
                        layout: 'form',
                        id: 'info_fieldset',
                        items: [
                            {
                                xtype: 'displayfield',
                                labelAlign: 'top',
                                fieldLabel: 'Data do pedido',
                                value: selected.data.created_at_formated,
                                name: 'date_reconsideration'
                            },
                            {
                                title: 'Texto redigido no recurso: ',
                                flex: 1,
                                border: false,
                                items: [
                                    {
                                        allowBlank: true,
                                        disabled:true,
                                        height:275,
                                        value: selected.data.text,
                                        name: 'text_reconsideration',
                                        xtype: "ckeditor"
                                    },
                                ]
                            },
                        ]
                    }
                ],
            }).show();
        }
        else{
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um recurso!'
            });
        }
    },

    decision: function(){
        var selected = this.getSelectionModel().getSelected();
        if (selected){
            var wnd = Ext._create('apd.decisioncommission.DecisionCommissionWindow', {
                action: 'create',
                scope:this,
                params: {
                    'resource_evaluation': selected.data.pk
                },
                callback: {
                    'success': {
                        'scope': this,
                        'fn': function() {
                            this.getStore().reload();
                        }
                    }
                }
            });
            wnd.show()
        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um recurso!'
            });
        }

    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 150, renderer: core.rendererIconGrid},
                    {header: 'Avaliação de APD', dataIndex: 'evaluation_unicode', id: 'autoExpandColumn'},
                    {header: 'Data da solicitação', dataIndex: 'created_at', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Prazo para julgar', dataIndex: 'days_to_judge', width: 250},
                    {header: 'Data ciência da decisão do recurso', dataIndex: 'date_science_decision', width: 200, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')}
                ]
            );

        return this._columnModel;
    },

    cleanFilter: function() {
        this._filterStatus = [1];
        this.setFilter([{'property': 'evaluation__subordinate__status__in', 'value': this._filterStatus, 'stage': 1000},]);
    }, 

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.apply(
            cfg,
            {   
                'viewConfig': {
                    getRowClass: function(record, rowIndex, rp, ds){ // rp = rowParams
                        if(record.data.deadline == 0)
                            return '';
                        if(record.data.deadline == 1)
                            return 'x-grid3-yellow-simple';
                        else if(record.data.deadline == 2)
                            return 'x-grid3-red-simple';
                    }
                },
                columnAction: false,
                allowCreate: false,
                allowUpdate: false,
                allowRemove: false,
            }
        );

        this.cleanFilter();

        apd.resource.ResourceGrid.superclass.constructor.call(this, cfg);
    }
});

core.RestfulGrid.register(
    'apd.resource.ResourceRestful',
    'apd.resource.ResourceGrid'
);

